# Generated by Opus 5-5

# Cross-conformation clash candidates from a neighbour search (the default source of clash candidates; see
# RestraintsHandler.load_all_constraints). Replaces the 20 A single-conformer table generated with phenix
# (PhenixEnvScripts/cross_conformation_clashes.py, still available with RestraintsHandler.PHENIX_CLASH_TABLE=True).
#
# Every pair of disordered sites with ANY of their conformers (any altloc pair, hydrogens included) within `cutoff`
# of each other, in the same asymmetric unit or via a crystal copy, is a candidate. As in the rest of Untangler, the 
# crystal copies are by default only those given by the REMARK 290 operators themselves, i.e. no contacts between 
# neighbouring unit cells (LatticeSymmetry.find_contacts_as_given). With translational_symmetries=True
# (see lattice_from_model; RestraintsHandler.SYMMETRY_LATTICE), each operator's nearest lattice translation is used instead
# (LatticeSymmetry.find_contacts). A clash needs the
# separation to be at least CLASH_OVERLAP_THRESHOLD below the vdw sum, so the default cutoff is the largest
# possible vdw sum minus that threshold (plus a margin). Whether a candidate becomes a clash restraint is then decided
# by RestraintsHandler's usual evaluation, which looks at all altloc pairs.
#
# Entries have the same format as get_cross_conf_nonbonds(): (pdb1, pdb2, vdw_sum, is_symm), with vdw sums from
# PhenixEnvScripts/clash_vdw.py (the same table the phenix script uses).

import numpy as np
from LinearOptimizer.Tag import OrderedTag, DisorderedTag
from LinearOptimizer import ClaudeLatticeSymmetry as LatticeSymmetry
from PhenixEnvScripts.clash_vdw import read_clash_table, pdb_key, VDW_RADII


def default_cutoff(clash_overlap_threshold:float, margin:float=0.1)->float:
    return 2*max(VDW_RADII.values()) - clash_overlap_threshold + margin


def lattice_from_cell(cell:list, symmetries:list, translational_symmetries:bool=False):
    '''(orthogonalisation matrix, fractionalisation matrix, fractional operators with the identity first,
    translational_symmetries): the crystal arguments of clash_candidates(). cell: [a, b, c, alpha, beta, gamma].
    translational_symmetries: whether crystal copies include lattice translations (contacts between neighbouring
    unit cells), or are only those given by the operators as they are.'''
    orth, frac = LatticeSymmetry.cell_matrices(*cell)
    frac_ops = LatticeSymmetry.identity_first(LatticeSymmetry.cartesian_ops_to_fractional(symmetries, orth, frac))
    return orth, frac, frac_ops, translational_symmetries


def lattice_from_model(pdb_file:str, symmetries:list, translational_symmetries:bool=False):
    '''As lattice_from_cell(), with the cell from the model's CRYST1 record. None if the model has no CRYST1.'''
    cell = LatticeSymmetry.cell_from_cryst1(pdb_file)
    if cell is None:
        return None
    return lattice_from_cell(cell, symmetries, translational_symmetries)



def _atom_table(lookup):
    tags, xyz, site_index, sites = [], [], [], {}
    for resnum, names in lookup.better_dict.items():
        for name, by_altloc in names.items():
            site_index_value = sites.setdefault(DisorderedTag(resnum, name), len(sites))
            for altloc, atom in by_altloc.items():
                tags.append(OrderedTag(resnum, name, altloc))
                xyz.append(atom.get_coord())
                site_index.append(site_index_value)
    return tags, np.array(xyz, dtype=float).reshape(-1, 3), np.array(site_index), sites


def clash_candidates(lookup, orth, frac, frac_ops, translational_symmetries:bool, cutoff:float,
                     target_resnums=None, target_tags=None)->list:
    '''
    lookup: OrderedAtomLookup (current coordinates).
    orth, frac, frac_ops, translational_symmetries: see lattice_from_model() / lattice_from_cell().
    target_tags (or target_resnums): only pairs involving these ordered atoms (residues). Default: all pairs.
    '''
    if not translational_symmetries:
        cart_ops = LatticeSymmetry.fractional_ops_to_cartesian(frac_ops, orth, frac)
    tags, xyz, site_index, sites = _atom_table(lookup)
    tag_index = {t: i for i, t in enumerate(tags)}
    # Target groups by residue (compact groups for the choice of lattice translation)
    groups = {}
    if target_tags is not None:
        for t in target_tags:
            if t in tag_index:
                groups.setdefault(t.resnum(), []).append(tag_index[t])
    else:
        for i, t in enumerate(tags):
            if target_resnums is None or t.resnum() in target_resnums:
                groups.setdefault(t.resnum(), []).append(i)
    rep_altloc = {}
    for t in tags:
        rep_altloc.setdefault(t.disordered_tag(), t.altloc())
    site_list = list(sites.keys())
    pairs = set()
    for resnum, idx in groups.items():
        idx = np.array(idx)
        if translational_symmetries:
            other_i, target_j, _, is_copy = LatticeSymmetry.find_contacts(xyz[idx], xyz, frac_ops, orth, frac, cutoff)
        else:
            other_i, target_j, _, is_copy = LatticeSymmetry.find_contacts_as_given(xyz[idx], xyz, cart_ops, cutoff)
        for o, t, c in zip(other_i, idx[target_j], is_copy):
            sa, sb = site_index[t], site_index[o]
            if sa == sb:
                continue
            if sa > sb:
                sa, sb = sb, sa  # one orientation per pair of sites
            pairs.add((int(sa), int(sb), bool(c)))
    entries = []
    vdw_cache = {}
    for sa, sb, is_symm in sorted(pairs):
        A, B = site_list[sa], site_list[sb]
        resA, resB = lookup.res_names[A.resnum()], lookup.res_names[B.resnum()]
        key = (resA, A.atom_name(), resB, B.atom_name())
        if key not in vdw_cache:
            vdw_cache[key] = read_clash_table(pdb_key(A.atom_name(), resA), pdb_key(B.atom_name(), resB))
        vdw = vdw_cache[key]
        if vdw is None:
            continue
        pdb1 = f"{A.atom_name():<4}{rep_altloc[A]}{resA.strip():>3} A{A.resnum():>4}"
        pdb2 = f"{B.atom_name():<4}{rep_altloc[B]}{resB.strip():>3} A{B.resnum():>4}"
        entries.append((pdb1, pdb2, vdw, is_symm))
    return entries
